// erzeugt aus dem Modell (graphcode vertragstest) — SCHEMA-steering-snapshot → src/kernel/measure/steering-snapshot.ts#SteeringSnapshotSchema. Nicht von Hand ändern, neu erzeugen.
import { describe, it, expect } from 'vitest';
import { SteeringSnapshotSchema as S } from '../../src/kernel/measure/steering-snapshot.js';

interface Z { _zod: { def: Record<string, unknown> } }
const bei = (weg: Array<[string, (string | number)?]>): Z =>
  weg.reduce<Z>((s, [art, k]) => {
    const d = s._zod.def;
    if (art === 'getter') return (d.getter as () => Z)();
    return k === undefined ? (d[art] as Z) : (d[art] as Record<string | number, Z>)[k]!;
  }, S as unknown as Z);

